function curIp() { return EXEC_MAP[state.ipId] || EXECS[0]; }
function isEn() { return state.lang === 'en'; }
function escapeHtml(s) { return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
function bi(zh, en, cls, tag) {
  var t = tag || 'span';
  return '<' + t + (cls ? ' class="' + cls + '"' : '') + ' data-i18n-zh="' + escapeHtml(zh) + '" data-i18n-en="' + escapeHtml(en) + '">' + escapeHtml(isEn() ? en : zh) + '</' + t + '>';
}

var toastTimer = null;
function showToast(msg) {
  var el = document.getElementById('muiSnackbar');
  if (!el) return;
  el.textContent = msg; el.classList.add('show');
  if (toastTimer) clearTimeout(toastTimer);
  toastTimer = setTimeout(function () { el.classList.remove('show'); }, 2400);
}

function loadChecks(id) {
  try {
    var raw = window.localStorage.getItem('snps_chk_' + id);
    if (raw) {
      var arr = JSON.parse(raw);
      if (Array.isArray(arr) && arr.length === 6) return arr.map(Boolean);
    }
  } catch (e) {}
  return [true, true, true, true, false, false];
}
function saveChecks(id, arr) {
  try { window.localStorage.setItem('snps_chk_' + id, JSON.stringify(arr)); } catch (e) {}
}

function renderPillGrid() {
  var grid = document.getElementById('ipPillGrid');
  if (!grid) return;
  grid.innerHTML = EXECS.map(function (ex) {
    var hidden = (state.execCat !== 'all' && ex.cat !== state.execCat) ? ' hidden-by-cat' : '';
    var act = ex.id === state.ipId ? ' active' : '';
    return '<button type="button" class="ip-pill-btn' + act + hidden + '" data-switch-ip="' + ex.id + '" data-exec-cat="' + ex.cat + '" aria-pressed="' + (ex.id === state.ipId) + '">' +
      '<span class="ip-pill-mono mono">' + ex.monogram + '</span>' +
      '<span class="ip-pill-text"><span class="ip-pill-name">' + ex.idx_pad + '. ' + escapeHtml(isEn() ? ex.short_en : ex.short_zh) + '</span>' +
      '<span class="ip-pill-meta mono">' + escapeHtml(ex.pill_kpi) + '</span></span></button>';
  }).join('');
}

