function renderPeerTable() {
  var tbody = document.getElementById('peerTableBody');
  var badge = document.getElementById('peerCountBadge');
  if (!tbody || !badge) return;
  var q = state.peerQuery.trim().toLowerCase();
  var rows = PEERS.filter(function (r) {
    if (state.peerFilter !== 'all' && r.cat !== state.peerFilter) return false;
    if (!q) return true;
    return (r.title + ' ' + r.creator + ' ' + r.format + ' ' + r.craft + ' ' + r.views + ' ' + r.acclaim + ' ' + r.takeaway).toLowerCase().indexOf(q) !== -1;
  });
  badge.textContent = '显示 ' + rows.length + ' / ' + PEERS.length + ' 项对标';
  tbody.innerHTML = rows.map(function (r) {
    return '<tr class="' + (r.benchmark ? 'benchmark-row' : '') + '"><td><strong style="color:var(--text-primary);display:block;">' + escapeHtml(r.title) + '</strong><span style="font-size:0.76rem;color:var(--text-muted);">' + escapeHtml(r.creator) + '</span></td>' +
      '<td>' + escapeHtml(r.format) + '</td><td>' + escapeHtml(r.craft) + '</td><td class="mono">' + escapeHtml(r.views) + '</td>' +
      '<td class="mono" style="color:var(--mui-primary-lighter);font-weight:700;">' + escapeHtml(r.acclaim) + '</td>' +
      '<td>' + escapeHtml(r.takeaway) + ' <a class="cite-link" href="' + r.sourceUrl + '" target="_blank" rel="noopener noreferrer">' + escapeHtml(r.sourceLabel) + ' ↗</a></td></tr>';
  }).join('');
}

