      ctx.fillStyle = pal.c2; topBar(ctx, x2, y2, bw, h2, 6); ctx.fill();
      valBadge(ctx, '$' + s2[i].toFixed(2) + u, x2 + bw / 2, Math.max(12, y2 - 12), pal.c2, pal);
