function drawRadarChart() {
  var env = prepCanvas('chartRadar'); if (!env) return;
  var ctx = env.ctx, w = env.w, h = env.h, pal = getPalette();
  hitRegions.chartRadar = [];
  var ip = curIp();
  var axes = isEn() ? ['EDA Depth', 'Ansys Synergy', 'Agentic AI', 'Margin/Cap', 'GTM/Eco'] : ['EDA/硅深度', 'Ansys融合', 'AI/智能体', '资本/利润率', '生态/GTM'];
  var hiAxis = hoverState.chartRadar >= 0 ? hoverState.chartRadar : [0, 1, 2, 4][state.activePillar];
  var series = [
    { key: 's0', name: ip.short_zh, color: pal.c1, fill: 'rgba(51,153,255,0.24)', vals: ip.radar },
    { key: 's1', name: 'Sassine Ghazi', color: pal.c2, fill: 'rgba(34,197,94,0.14)', vals: EXECS[0].radar },
    { key: 's2', name: '同业高管均值', color: pal.c3, fill: 'rgba(255,183,77,0.12)', vals: [8.5, 8.6, 8.7, 8.6, 8.8] }
  ];
  var cx = w / 2, cy = h / 2 + 8, radius = Math.max(60, Math.min((w - 190) / 2, h * 0.35));
  for (var ring = 2; ring <= 10; ring += 2) {
    var r = (ring / 10) * radius; ctx.strokeStyle = pal.grid; ctx.beginPath();
    for (var i = 0; i < 5; i++) {
      var a = -Math.PI / 2 + (i * 2 * Math.PI) / 5;
      if (i === 0) ctx.moveTo(cx + Math.cos(a) * r, cy + Math.sin(a) * r);
      else ctx.lineTo(cx + Math.cos(a) * r, cy + Math.sin(a) * r);
    }
    ctx.closePath(); ctx.stroke();
  }
  for (var a = 0; a < 5; a++) {
    var ang = -Math.PI / 2 + (a * 2 * Math.PI) / 5;
    var ax = cx + Math.cos(ang) * radius, ay = cy + Math.sin(ang) * radius;
    ctx.strokeStyle = a === hiAxis ? pal.c1 : pal.grid; ctx.lineWidth = a === hiAxis ? 1.8 : 1;
    ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(ax, ay); ctx.stroke();
    var lx = cx + Math.cos(ang) * (radius + 16), ly = cy + Math.sin(ang) * (radius + 16);
    ctx.fillStyle = a === hiAxis ? pal.c1 : pal.text; ctx.font = (a === hiAxis ? '800 ' : '600 ') + '11.5px system-ui, sans-serif';
    ctx.textAlign = Math.abs(Math.cos(ang)) < 0.2 ? 'center' : (Math.cos(ang) > 0 ? 'left' : 'right');
    ctx.textBaseline = 'middle'; ctx.fillText(axes[a], lx, ly);
    hitRegions.chartRadar.push({ idx: a, x: Math.min(ax, lx) - 30, y: Math.min(ay, ly) - 20, w: 60 + Math.abs(lx - ax), h: 40,
      html: '<strong>' + axes[a] + '</strong><br/>• ' + ip.short_zh + ': ' + ip.radar[a] + '<br/>• CEO 基准: ' + EXECS[0].radar[a] });
  }
  for (var s = 0; s < series.length; s++) {
    var it = series[s]; if (!state.radarSeries[it.key]) continue;
    ctx.beginPath();
    for (var k = 0; k < 5; k++) {
      var th = -Math.PI / 2 + (k * 2 * Math.PI) / 5, dist = (it.vals[k] / 10) * radius;
      if (k === 0) ctx.moveTo(cx + Math.cos(th) * dist, cy + Math.sin(th) * dist);
      else ctx.lineTo(cx + Math.cos(th) * dist, cy + Math.sin(th) * dist);
    }
    ctx.closePath(); ctx.fillStyle = it.fill; ctx.fill(); ctx.strokeStyle = it.color; ctx.lineWidth = 2.2; ctx.stroke();
  }
}

